SELECT u.user_id, u.department_id, u.name, u.tel, u.mail, u.role,uc.role AS ucrole FROM tbl_user u JOIN tbl_user_club uc ON u.user_id = uc.user_id WHERE uc.club_id = #{clubId} AND uc.is_deleted = 0 AND u.is_deleted = 0
AND u.name like concat('%',#{name},'%')
AND u.department_id = #{departmentId}
